export function getArticleContent<T extends ArticleContent>(
  slug: string,
  locale: Locale,
  fallback: T
): ArticleContent {
  if (locale === "en") return fallback;
  return articleContentTranslations[slug]?.[locale as TranslatedLocale] ?? fallback;
}
